output:
```python
import functools
import logging
import random
import time

logger = logging.getLogger(__name__)


def retry(
    attempts=3,
    delay=1.0,
    backoff=2.0,
    max_delay=None,
    jitter=False,
    exceptions=(Exception,),
):
    """Re-run a function when it raises, backing off exponentially between tries.

    attempts:   total number of calls, including the first one.
    delay:      seconds to wait before the second attempt.
    backoff:    multiplier applied to the delay after each failure.
    max_delay:  optional ceiling on the wait between attempts.
    jitter:     if true, wait a random duration in [0, delay) instead of delay,
                which keeps many concurrent callers from retrying in lockstep.
    exceptions: exception type or tuple of types that should trigger a retry;
                anything else propagates immediately.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            current = delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        raise
                    wait = random.uniform(0, current) if jitter else current
                    logger.warning(
                        "%s failed on attempt %d/%d (%s); retrying in %.2fs",
                        func.__name__, attempt, attempts, exc, wait,
                    )
                    time.sleep(wait)
                    current *= backoff
                    if max_delay is not None:
                        current = min(current, max_delay)

        return wrapper

    return decorator
```

Usage:

```python
@retry(attempts=5, delay=0.5, backoff=2, max_delay=10, jitter=True,
       exceptions=(ConnectionError, TimeoutError))
def fetch(url):
    ...
```

The last failure's exception propagates unchanged (with its original traceback), so callers see the real error rather than a wrapper. Waits go 0.5s, 1s, 2s, 4s — capped at `max_delay`.
